): Promise<Page<ActivityEvent>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:read", activityResource(input.orgId));
  return activityRepo.listActivity(input);
}

/**
 * Every entry in the range, newest first, across as many pages as it takes.
 * The range is inclusive at both ends, so `since === until` is a valid
 * single-instant query and a range ending before it starts is refused.
 */
export async function listActivityForExport(
  actor: Actor,
  input: ExportActivityInput,
): Promise<readonly ActivityEvent[]> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "activity:export", activityResource(input.orgId));

  if (Date.parse(input.until) < Date.parse(input.since)) {
    throw new RangeError("until must not be before since");
  }

  const entries: ActivityEvent[] = [];
  let cursor: string | null = null;

  do {
    const page: Page<ActivityEvent> = await activityRepo.listActivity({
      orgId: input.orgId,
      since: input.since,
      until: input.until,
      limit: EXPORT_BATCH_LIMIT,
      cursor,
    });
    entries.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return entries;
